  [21007] = { "Riduce i danni fisici inflitti dai nemici vicini di $N1 per $D1. Su un bersaglio può essere attiva solo una maledizione per Stregone alla volta.", "Danni fisici inflitti ridotti di $N1.", 0xdbb935e0, 0x7e5a09cd, "uu" },
