  [21051] = { "Usalo per far entrare i parassiti che infestano il ⟦Deeprun Tram=Tram degli Abissi⟧ in uno stato di rapimento estatico.", nil, 0x03a75d04, nil, "um" },
  [21055] = { "Colpisce l'armatura di un nemico, riducendola di $N1 per ogni applicazione di ⟦Crush Armor=Spacca Armatura⟧. Cumulabile fino a $N2 volte. Dura $D1.", "Armatura ridotta.", 0xe00702ba, 0xc3d1fc4c, "uu" },
  [21056] = { nil, "$N1 mana prosciugato ogni $N2 s.\nEsplode se non c'è mana da prosciugare.", nil, 0x02b3a481, "mu" },
