  [21060] = { "Acceca il bersaglio, costringendolo a vagare senza meta per un massimo di $D1. Eventuali danni inflitti al bersaglio interrompono l'effetto.", "Confuso.", 0xc8621c09, 0xddba7701, "uu" },
  [21061] = { "Fornisce una probabilità di lanciare ⟦Putrid Breath=Alito Putrido⟧ contro il nemico dopo un attacco in mischia subito.", nil, 0xc819450f, nil, "um" },
  [21063] = { nil, "In seguito ai danni, l'attaccante viene curato di $N1.", nil, 0xb39e7553, "mu" },
