  [21067] = { "Lancia veleno contro un bersaglio nemico, infliggendo danni da natura e danni aggiuntivi ogni $N1 s per $D2.", "Danni da natura inflitti ogni $N1 s.", 0x2c66ca3a, 0xaae6fcde, "uu" },
  [21068] = { "Corrompe i nemici vicini, infliggendo danni da ombra ogni $D1 per $D2.", "Danni da ombra inflitti ogni $N1 s.", 0x8972582c, 0x4cc78b5e, "uu" },
  [21069] = { "Avvelena i nemici vicini infliggendo $N1 danni e $N2 danni da natura aggiuntivi ogni $N3 s per $D2.", "$N1 danni da natura inflitti ogni $N2 s.", 0x2a59eb8a, 0xd8c7b0a1, "uu" },
