  [21072] = { "Infligge danni da fuoco a un nemico.", nil, 0x6c371710, nil, "um" },
  [21073] = { "Emana un'ondata di magia che infligge danni da arcano ai nemici vicini.", nil, 0xb94462fd, nil, "um" },
  [21075] = { nil, "$N1 danni inflitti agli attaccanti in mischia.", nil, 0x6f6bb04d, "mu" },
