  [21080] = { "Fornisce una probabilità di lanciare ⟦Putrid Breath=Alito Putrido⟧ contro il nemico dopo un attacco in mischia subito.", nil, 0xc819450f, nil, "um" },
  [21081] = { nil, "Armatura ridotta.", nil, 0xc3d1fc4c, "mu" },
  [21082] = { "Pervade il Paladino dello spirito di un crociato per $D1, aumentando di $N2 la potenza d'attacco in mischia. Inoltre il Paladino attacca il $N3% più velocemente, ma infligge meno danni con ogni attacco. Sul Paladino può essere attivo un solo Sigillo alla volta.\n\nLiberare l'energia di questo Sigillo sottopone un nemico al Giudizio per $D2, aumentando i danni da sacro che subisce fino a un massimo di $N5. I tuoi colpi in mischia rinnovano la durata dell'incantesimo. Può essere attivo un solo Giudizio per Paladino alla volta.", "Potenza d'attacco in mischia aumentata di $N1. Gli attacchi in mischia sono più veloci del $N2%, ma infliggono meno danni.", 0x6927fef5, 0xf3c132e9, "uu" },
  [21084] = { "Pervade il Paladino di spirito sacro per $D1, conferendo a ogni attacco in mischia $N2 danni da sacro aggiuntivi. Le armi più lente infliggono più danni da sacro a ogni colpo. Sul Paladino può essere attivo un solo Sigillo alla volta.\n\nLiberare l'energia di questo Sigillo infligge $N3 danni da sacro a un nemico.", "Gli attacchi in mischia infliggono $N1 danni da sacro aggiuntivi.", 0x3e078aee, 0x8d406bfa, "uu" },
  [21088] = { "⟦Arcane Intellect=Intelletto Arcano⟧ fornisce +$N1 Intelletto del normale.", nil, 0x808a60e3, nil, "um" },
  [21091] = { nil, "La successiva Punizione richiede meno mana.", nil, 0x5654cca2, "mu" },
  [21092] = { "Aumenta del $N1% la tua probabilità di critico magico.", nil, 0xd715ed95, nil, "um" },
  [21093] = { "⟦Power Word: Fortitude=Parola del Potere: Fermezza⟧ fornisce +$N1 Tempra del normale.", nil, 0x40ae9e57, nil, "um" },
  [21096] = { "Richiama una tormenta che dura $D1, infliggendo $N2 danni da gelo ogni $N3 s a tutti i nemici in un'area bersaglio.", nil, 0xc6937fbd, nil, "um" },
  [21097] = { "Evoca una tempesta di mana che dura $D1, infligge $N2 danni da gelo e prosciuga $N3 mana ogni $N4 s a tutti i nemici in un'area bersaglio.", nil, 0xe9d85538, nil, "um" },
  [21098] = { "Investe i nemici vicini con il ghiaccio, infliggendo $N1 danni, aumentando l'intervallo tra i loro attacchi del $N2% e riducendone la velocità di movimento del $N3%.", "Intervallo tra gli attacchi aumentato del $N1%.\nVelocità di movimento ridotta del $N2%.", 0x01056e5b, 0x83ffb7cf, "uu" },
  [21099] = { "Infligge danni da gelo ai nemici in un cono frontale, rubando loro il mana e riducendone la velocità di movimento per $D1.", nil, 0x03102da3, nil, "um" },
  [21109] = { "Rigenera $N1 salute ogni $D1.", "Rigenera $N1 salute ogni $D1.", 0xb1936106, 0xb1936106, "uu" },
