  [21134] = { "Infonde stupore e meraviglia negli adoratori di Ragnaros.", "Emette la ⟦Will of Ragnaros=Volontà di Ragnaros⟧.", 0x3c196d18, 0x267012d5, "uu" },
  [21140] = { "Causa una ferita fatale che infligge $N1 danni.", nil, 0x262f20f0, nil, "um" },
