  [21142] = { "Infligge $N1 danni da fuoco a chiunque ti colpisca in mischia.", nil, 0xdddae426, nil, "um" },
  [21149] = { "Rigenera $N1 salute in $D1. Devi sederti per mangiare. Se mangi per almeno $N3 s diventi Ben Nutrito e ottieni $N4 Tempra e Spirito per $D2. E poi è bello forte...", "$N1 salute rigenerata ogni secondo.", 0x31e8da74, 0xfde4540f, "uu" },
  [21151] = { "Lancia un dardo d'ombra contro il nemico, infliggendo $N1 danni da ombra e riducendo tutti gli attributi di $N2 per $D1.", nil, 0x17a1cf02, nil, "um" },
